#include <map>
#include <string>
#include <iostream>

// Case-insensitive comparison functor
struct IgnoreCaseCmp {
    bool operator()(const std::string& a, const std::string& b) const {
        // Simplified case-insensitive comparison
        return strcasecmp(a.c_str(), b.c_str()) < 0;
    }
};

int main() {
    // Map uses IgnoreCaseCmp to define both order and uniqueness
    std::map<std::string, int, IgnoreCaseCmp> m;

    m.insert({"Apple", 1});
    // "apple" is equivalent to "Apple" per IgnoreCaseCmp
    m.insert({"apple", 2}); 

    // Size is 1, not 2. Value 2 was discarded.
    std::cout << m.size() << std::endl; // Output: 1

    // The key retained is implementation-dependent or based on insertion order.
}
